    tip = a.toolTip() or ''
    if ('ラベル' in t or 'ダイアグラム' in t or 'label' in a.objectName().lower() or 'diagram' in a.objectName().lower()):
        found.append({'objectName': a.objectName(), 'text': t, 'enabled': a.isEnabled(), 'checkable': a.isCheckable(), 'checked': a.isChecked(), 'tooltip': tip[:150]})
